package xyz.jasenon.lab.storage;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.util.HexFormat;
/** Private streaming storage. Keys are generated by the business service. */
public interface ObjectStorage {
    void put(String bucket, String key, InputStream input, long size, String contentType) throws Exception;
    InputStream get(String bucket, String key) throws Exception;
    String downloadUrl(String bucket, String key, int seconds) throws Exception;
    default String sha256(String bucket, String key) throws Exception {
        try (InputStream input = get(bucket, key)) { return digest(input); }
    }
    static String digest(InputStream input) throws Exception {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        byte[] buffer = new byte[65536];
        for (int n; (n = input.read(buffer)) != -1;) digest.update(buffer, 0, n);
        return HexFormat.of().formatHex(digest.digest());
    }
    default String uploadVerified(String bucket, String key, Path file, String contentType) throws Exception {
        String expected;
        try (InputStream input = Files.newInputStream(file)) { expected = digest(input); }
        try (InputStream input = Files.newInputStream(file)) { put(bucket, key, input, Files.size(file), contentType); }
        if (!expected.equals(sha256(bucket, key))) throw new IllegalStateException("Object checksum mismatch: " + key);
        return expected;
    }
}
